let w:VueWrapper|undefined,router:Router,fixture:ReturnType<typeof controlFixture>,profileWrong:boolean,holdPost:((response:Response)=>Promise<Response>)|undefined
let observed:{path:string;method:string}[]
let downlink:DataDownlinkFunction|undefined,previewCount=0,previewNull=false,wrongAction=false
let dataMode=false,dataUnknown=false,dataActive=false,dataFollowupFail=false
const streams=[{identifier:'raw_hex',name:'原HEX',format:'HEX'},{identifier:'raw_json',name:'原JSON',format:'JSON'},{identifier:'sensor_text',name:'传感文本',format:'TEXT'}]
const publication=()=>JSON.stringify({revision:'1',publication:{publicationId:device,schemaProfile:'TL_DATA_STREAM_DEFINITION_V1',digestAlgorithm:'PG_JSONB_TEXT_V1_SHA256',definitionDigest:'c'.repeat(64),definition:{streams,tcpStreamIdentifier:null},publishedAt:'2026-10-30T00:00:00Z',activation:'NEXT_CONNECTION',managementDetails:streams.map(s=>({identifier:s.identifier,description:null,createdAt:null}))}})
async function fetcher(input:RequestInfo|URL,init?:RequestInit){const url=new URL(String(input)),method=init?.method||'GET';observed.push({path:url.pathname,method})
 if(url.pathname===`/api/v1/projects/${project}/device-types/${type}`)return fixture.response(JSON.stringify({id:type,projectId:profileWrong?type:project,name:'权威前处理类型'}))
 if(dataMode&&url.pathname.endsWith('/device-types/search'))return fixture.response(JSON.stringify({items:[{id:type,name:'权威前处理类型'}],hasMore:false,nextCursor:null}))
 if(url.pathname===`/api/v1/projects/${project}/device-types/${type}/profile`)return fixture.response(JSON.stringify({type:{id:type,projectId:profileWrong?type:project,name:'权威前处理类型',deviceKind:'DIRECT',networkType:'WIFI',payloadProtocol:'STANDARD',status:'DRAFT'},description:null,tags:{},revision:'0',profileToken:'a'.repeat(64)}))
 if(url.pathname.endsWith('/data-stream-publication'))return fixture.response(publication())
 if(dataMode&&method==='POST'&&url.pathname.endsWith('/data-downlink-previews')){
  previewCount++;const body=JSON.parse(String(init?.body));expect(Object.keys(body).sort()).toEqual(['payloadBase64','source','streamIdentifier']);expect(body.streamIdentifier).toBe('raw_hex');expect(body.source).toContain('function(identifier, data)');
  return fixture.response(JSON.stringify(previewNull?{outputJson:'null',format:null,payloadBase64:null,payloadBytes:0}:{outputJson:'{"type":"json","msg":{"var1":1,"var2":true}}',format:'JSON',payloadBase64:btoa('{"var1":1,"var2":true}'),payloadBytes:22}))
 }
 if(dataMode&&method==='POST'&&url.pathname.endsWith('/preprocessors')&&JSON.parse(String(init?.body)).dataDownlink){
  const body=JSON.parse(String(init?.body));fixture.state.calls.push({path:url.pathname,method,body:String(init?.body),headers:new Headers(init?.headers)});expect(body.functions).toBeUndefined();expect(body.nativeParser).toBeUndefined();expect(body.streamIdentifier).toBe('raw_hex');downlink=body.dataDownlink;fixture.state.created=true;fixture.state.name=body.name;fixture.state.description=body.description||null;fixture.state.tags=body.tags;if(dataFollowupFail)fixture.state.readError=503;return fixture.response(fixture.header(),201)
 }
 if(downlink&&method==='GET'&&(url.pathname.includes('/versions/')||url.pathname.endsWith('/version-history'))){
  if(fixture.state.readError)return fixture.response('{"message":"后继读取失败"}',fixture.state.readError)
  const version={id:fixture.state.versionId,versionNumber:1,source:downlink.source,sourceSha256:createHash('sha256').update(downlink.source).digest('hex'),createdBy:project,createdAt:'2026-10-30T00:00:00Z',actions:[],deviceSource:{kind:'DEVICE_TYPE',referenceId:type},preprocessing:null,sourceFormat:wrongAction?'MODBUS_RTU_V1':dataDownlinkSourceFormat(downlink),streamIdentifier:'raw_hex',dataDownlink:downlink}
  return fixture.response(JSON.stringify(url.pathname.endsWith('/version-history')?{items:[version],nextCursor:null}:version))
 }

 if(dataMode&&method==='POST'&&url.pathname.endsWith('/preprocessors')){
  fixture.state.calls.push({path:url.pathname,method,body:String(init?.body),headers:new Headers(init?.headers)});const body=readRawRuleJson(new TextEncoder().encode(String(init?.body)));fixture.state.created=true;fixture.state.name=body.at(['name']).string();fixture.state.description=body.at(['description']).string()||null;fixture.state.tags=JSON.parse(body.at(['tags']).raw());fixture.state.preprocessing='{"trigger":{"kind":"DATA_RPT","identifier":'+body.at(['streamIdentifier']).raw()+',"filter":{"operator":"ALL","conditions":[],"groups":[]}},"functions":'+body.at(['functions']).raw()+'}'
  if(dataFollowupFail)fixture.state.readError=503
  if(dataUnknown)throw new TypeError('synthetic DATA creation response lost')
  return fixture.response(fixture.header(),201)
 }
 if(dataMode&&method==='POST'&&url.pathname.endsWith('/activate')){fixture.state.calls.push({path:url.pathname+url.search,method,body:String(init?.body??''),headers:new Headers(init?.headers)});expect(url.searchParams.get('expectedVersion')).toBe('1');dataActive=true;fixture.state.version='2';return fixture.response(fixture.header().replace('"status":"PAUSED"','"status":"ACTIVE"'))}
 let response=await fixture.fetcher(input,init)
 if(dataMode&&dataActive&&url.pathname===`/api/v1/projects/${project}/message-rules/${rule}`)response=fixture.response((await response.text()).replace('"status":"PAUSED"','"status":"ACTIVE"'))
 if(response.status===200&&(url.pathname.includes('/versions/')||url.pathname.endsWith('/version-history'))){const source=readRawRuleJson(new TextEncoder().encode(fixture.state.preprocessing)).at(['functions',0,'source']).string(),digest=createHash('sha256').update(source).digest('hex');response=fixture.response((await response.text()).replace('"sourceSha256":"'+'a'.repeat(64)+'"','"sourceSha256":"'+digest+'"').replace('"deviceSource":{"kind":"DEVICE","referenceId":"'+device+'"}','"deviceSource":{"kind":"DEVICE_TYPE","referenceId":"'+type+'"}'))}
 return method==='POST'&&holdPost?holdPost(response):response
}
async function render(){router=createRouter({history:createMemoryHistory(),routes:[...ruleRoutes,{path:'/device-types/:id',component:{render:()=>h('p','类型消息规则页')}},{path:'/away',component:{render:()=>h('p','已离开')}}]});await router.push(`/rules/messages/create?source=device-type&deviceTypeId=${type}`);await router.isReady();w=mount(RouterView,{attachTo:document.body,global:{plugins:[router,ElementPlus]}});await flushPromises();return w}
function button(label:string){const found=w!.findAll('button').find(x=>x.text()===label||x.attributes('aria-label')===label);expect(found,label).toBeDefined();return found!}
function lastDialogButton(label:string){const dialogs=document.body.querySelectorAll('.el-dialog'),part=new DOMWrapper(dialogs.item(dialogs.length-1)??document.body),found=part.findAll('button').find(x=>x.text()===label);expect(found,label).toBeDefined();return found!}
