 const field=new DOMWrapper(document.body).get('[aria-label="'+actual+'"]')
 expect((field.element instanceof HTMLTextAreaElement?field.element.value:field.text()).trim()).toBe(source.trim())
 expect(w!.find('[aria-label="修订规则名称"]').exists()).toBe(false)
 await detailDialogButton('取消').trigger('click');await flushPromises()
