it('TYPE五Tab保留原内容，信息与标签用精确CAS保存回读，标签未知只读恢复并从目录返回',async()=>{
 fixture.state.created=true;fixture.state.version='3';fixture.state.directorySource={kind:'DEVICE_TYPE',referenceId:type}
 const original=fetcher,requests:{method:string;body:string}[]=[];let loseTagReply=false
 vi.stubGlobal('fetch',vi.fn(async(input:RequestInfo|URL,init?:RequestInit)=>{
  const url=new URL(String(input)),method=init?.method??'GET'
  if(method==='PUT'&&url.pathname===`/api/v1/projects/${project}/message-rules/${rule}`){
   const body=String(init?.body),value=readRawRuleJson(new TextEncoder().encode(body));requests.push({method,body})
   expect(url.searchParams.get('informationOnly')).toBe('true');expect(value.at(['expectedVersion']).integerText()).toBe(fixture.state.version);expect([...value.keys()].sort()).toEqual(['description','expectedVersion','name'])
   fixture.state.name=value.at(['name']).string();fixture.state.description=value.at(['description']).string();fixture.state.version=String(BigInt(fixture.state.version)+1n);return fixture.response(fixture.header())
  }
  if(method==='PUT'&&url.pathname.endsWith('/tags')){
   const body=String(init?.body),value=readRawRuleJson(new TextEncoder().encode(body));expect(value.at(['expectedVersion']).integerText()).toBe(fixture.state.version);requests.push({method,body})
   const response=await original(input,init);if(loseTagReply)throw new TypeError('synthetic tags response lost');return response
  }
  return original(input,init)
 }))
 const view=await render();await router.push(`/rules/messages/${rule}?source=device-type&deviceTypeId=${type}&origin=directory&tab=settings`);await flushPromises();await vi.waitFor(()=>expect(view.findAll('[role="tab"]')).toHaveLength(5))
 expect(view.findAll('[role="tab"]').map(row=>row.text())).toEqual(['规则','设备','统计','日志','设置']);expect(view.text()).toContain('完整描述');expect(view.text()).toContain('机房');expect(view.find('[aria-label="类型规则函数源码"]').exists()).toBe(false)
 const currentDialog=()=>new DOMWrapper(document.body.querySelectorAll('.el-dialog').item(document.body.querySelectorAll('.el-dialog').length-1)!)
 await view.get('.reference-object-heading .rule-name button').trigger('click');await flushPromises();let dialog=currentDialog();await dialog.get('[aria-label="规则名称"]').setValue('信息修订');await dialog.get('[aria-label="规则描述"]').setValue('只改信息');await dialog.findAll('button').find(row=>row.text()==='保存')!.trigger('click');await vi.waitFor(()=>expect(view.text()).toContain('只改信息'))
 expect(fixture.state.version).toBe('4');expect(requests).toHaveLength(1);expect(fixture.state.versionNumber).toBe('1')
 const settings=view.get('.rule-settings');await settings.findAll('button').reverse().find(row=>row.text()==='编辑')!.trigger('click');await flushPromises();dialog=currentDialog();await dialog.get('[aria-label="标签 1 值"]').setValue('二号机房');loseTagReply=true;await dialog.findAll('button').find(row=>row.text()==='提交')!.trigger('click');await vi.waitFor(()=>expect(view.text()).toContain('操作结果未知'));expect(requests).toHaveLength(2)
 await button('读取原操作核对').trigger('click');await vi.waitFor(()=>expect(view.text()).toContain('已读取并核对保存结果'));expect(view.text()).toContain('二号机房');expect(fixture.state.version).toBe('5');expect(requests).toHaveLength(2)
 await button('移除规则').trigger('click');await flushPromises();dialog=currentDialog();await dialog.findAll('button').find(row=>row.text()==='取消')!.trigger('click');expect(requests).toHaveLength(2)
 await button('返回').trigger('click');await vi.waitFor(()=>expect(router.currentRoute.value.path).toBe('/rules/messages'))
})

