 fixture.state.created=true;fixture.state.version='3';fixture.state.directorySource={kind:'DEVICE_TYPE',referenceId:type}
 let posts=0,reads=0,key=''
 vi.stubGlobal('fetch',vi.fn(async(input:RequestInfo|URL,init?:RequestInit)=>{
  const url=new URL(String(input)),method=init?.method??'GET'
  if(url.pathname.endsWith('/deletions')&&method==='POST'){posts++;key=new Headers(init?.headers).get('Idempotency-Key')!;expect(key).toBeTruthy();expect(JSON.parse(String(init?.body))).toEqual({expectedDefinitionVersion:'3'});throw new TypeError('lost deletion response')}
  if(url.pathname.endsWith('/deletions/by-key')){reads++;expect(method).toBe('GET');expect(new Headers(init?.headers).get('Original-Request-Key')).toBe(key);expect(url.search).toBe('');return reads===1?Response.json({message:'未查到原件'},{status:404}):Response.json({projectId:project,ruleId:rule,actorId:project,expectedDefinitionVersion:'3',deletedDefinitionVersion:'4',deletedAt:'2026-11-01T08:00:00Z'})}
  return fetcher(input,init)
 }))
